    if tokens.pop(0).value != "TABLE":
        raise SQLSyntaxError("Expected TABLE")
    table_name = _expect_identifier(tokens)
    if tokens.pop(0).value != "(":
        raise SQLSyntaxError("Expected (")
    columns = []
    while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ")":
        column_name = _expect_identifier(tokens)
        if tokens[0].type != TokenType.KEYWORD or tokens[0].value not in ("INTEGER", "TEXT", "BOOLEAN"):
