    return SelectStmt(table_name, tuple(columns) if columns else None, where_expr)


def _parse_delete(tokens: list[Token]) -> DeleteStmt:
    if tokens.pop(0).value != "FROM":
        raise SQLSyntaxError("Expected FROM")
    table_name = _expect_identifier(tokens)
    where_expr = None
    if tokens and tokens[0].value == "WHERE":
        tokens.pop(0)
        where_expr = parse_expression(tokens)
    _consume_semicolon(tokens)
    return DeleteStmt(table_name, where_expr)


def _expect_identifier(tokens: list[Token]) -> str:
    token = tokens.pop(0)
    if token.type != TokenType.IDENTIFIER:
        raise SQLSyntaxError(f"Expected identifier, got {token}")
    return token.value


def _parse_literal(token: Token) -> Value:
    if token.type == TokenType.INTEGER:
        return int(token.value)
    elif token.type == TokenType.STRING:
        return token.value
    elif token.type == TokenType.KEYWORD:
        if token.value == "TRUE":
            return True
        elif token.value == "FALSE":
            return False
        elif token.value == "NULL":
            return None
    raise SQLSyntaxError(f"Unexpected literal: {token}")


def _parse_or_expr(tokens: list[Token]) -> Expr:
    expr = _parse_and_expr(tokens)
    while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "OR":
        tokens.pop(0)
        expr = Or(expr, _parse_and_expr(tokens))
    return expr


def _parse_and_expr(tokens: list[Token]) -> Expr:
    expr = _parse_not_expr(tokens)
    while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "AND":
        tokens.pop(0)
        expr = And(expr, _parse_not_expr(tokens))
    return expr


def _parse_not_expr(tokens: list[Token]) -> Expr:
    if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
        tokens.pop(0)
        return Not(_parse_predicate(tokens))
    return _parse_predicate(tokens)


def _parse_predicate(tokens: list[Token]) -> Expr:
    left = _parse_primary(tokens)
    if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value in COMPARISON_OPS:
        op = tokens.pop(0).value
        right = _parse_primary(tokens)
        return Comparison(op, left, right)
    elif tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "IS":
        tokens.pop(0)
        negated = False
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
            tokens.pop(0)
            negated = True
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NULL":
            tokens.pop(0)
            return IsNull(left, negated)
    return left


def _parse_primary(tokens: list[Token]) -> Expr:
    token = tokens.pop(0)
    if token.type == TokenType.INTEGER:
        return Literal(int(token.value))
    elif token.type == TokenType.STRING:
        return Literal(token.value)
    elif token.type == TokenType.KEYWORD:
        if token.value == "TRUE":
            return Literal(True)
        elif token.value == "FALSE":
            return Literal(False)
        elif token.value == "NULL":
            return Literal(None)
    elif token.type == TokenType.IDENTIFIER:
        return ColumnRef(token.value)
    elif token.type == TokenType.OPERATOR and token.value == "(":
        expr = parse_expression(tokens)
        if tokens.pop(0).value != ")":
            raise SQLSyntaxError("Expected )")
        return expr
    raise SQLSyntaxError(f"Unexpected token: {token}")


def _consume_semicolon(tokens: list[Token]):
    if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
        tokens.pop(0)
